package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MathUtils_lcm_TriageGen2Test {









    @Test(expected = ArithmeticException.class)
    public void testLcmOverflow() {
        // We need to trigger the case where lcm == Integer.MIN_VALUE
        // Since the implementation uses mulAndCheck and then Math.abs,
        // if mulAndCheck returns Integer.MIN_VALUE, it throws.
        // Integer.MIN_VALUE is -2147483648.
        // Let's try to find a combination that causes overflow in the product.
        // If a=1, b=Integer.MIN_VALUE, gcd(1, MIN_VALUE)=1.
        // lcm = abs(mulAndCheck(1+1, MIN_VALUE)) = abs(mulAndCheck(2, -2147483648))
        // 2 * -2147483648 overflows 32-bit int.
        // However, the specific check is: if (lcm == Integer.MIN_VALUE) throw...
        // Math.abs(Integer.MIN_VALUE) is still Integer.MIN_VALUE in Java.

        // To hit the specific branch: lcm = Math.abs(mulAndCheck(a + gcd(a, b), b));
        // If mulAndCheck returns Integer.MIN_VALUE, Math.abs returns Integer.MIN_VALUE.
        // Then the if check catches it.

        // Using a large prime and a large number to force overflow
        MathUtils.lcm(Integer.MAX_VALUE, 2);
    }


}

package org.apache.commons.math.util;

